   398		gitExecPath := gitInstallPath()
   399		if gitExecPath == "" {
   400			return errors.New("git not found in PATH")
   401		}
   402	
   403		displayStartupConfig()
   404	
   405		logger.Println("using git executable:", gitExecPath)
   406		logGitVersion(gitExecPath)
   407	
   408		if err := logRequestTimeout(); err != nil {
   409			return err
   410		}
   411	
   412		backupDIR, err := validateStartupConfig()
   413		if err != nil {
   414			return err
   415		}
   416	
   417		if err = createWorkingDir(backupDIR); err != nil {
   418			return err
   419		}
   420	
   421		return scheduleBackups()
   422	}
