   473	func createWorkingDir(backupDIR string) error {
   474		// Check if GIT_WORKING_DIR is set, otherwise use default
   475		workingDIR := os.Getenv(envGitWorkingDir)
   476		if workingDIR == "" {
   477			workingDIR = filepath.Join(backupDIR, workingDIRName)
   478		}
   479	
   480		logger.Println("creating working directory:", workingDIR)
   481	
   482		if mkErr := os.MkdirAll(filepath.Clean(workingDIR), workingDIRMode); mkErr != nil {
   483			return errors.Wrap(mkErr, fmt.Sprintf("failed to create working directory %q", workingDIR))
   484		}
   485	
   486		return nil
   487	}
